"In this code following notations are used for ease, adding description for it to better understand what each parameter stands for:"

"Model Inputs"
"P_1 - Suction pressure"
"P_2 - Injection pressure"
"P_3 - Discharge Pressure"
"rho_inj - Injection density"
"rho_suc - Suction density"
"F - Compressor speed (rpm)"
"T_inj - Injection temperature"
"T_s - suction temperature"



"Model Outputs"
"m_dot_i -  injection mass flow rate"
"m_dot_e - suction mass flow rate"
"W_dot - Compressor Power"
"T_dis - Discharge Temperature"





"Injection mass flow rate model"

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.optimize import curve_fit
from sklearn.metrics import mean_absolute_percentage_error, mean_absolute_error , root_mean_squared_error
from matplotlib.lines import Line2D

#Define compressor non-linear model
def fun_I1(x, a0, a1, a2, a3, a4, a5):
    rho_inj, F, P_1, P_2, P_3, T_inj = x  # Ensure correct input unpacking
    KB = a0+a1* rho_inj *((1 - (P_1 / P_2) ** a3)** a2)*((1/T_inj )** a4)*((F / F[2]) ** a5)
    return KB

# Load data from Excel
filename = "Compressor Data.xlsx"

df_train = pd.read_excel(filename, sheet_name=0)  # Training set
df_test = pd.read_excel(filename, sheet_name=0)   # Testing set

# Extract independent and dependent variables

x_train = (
    df_train["rho_inj"],
    df_train["F"],
    df_train["P_1"],
    df_train["P_2"],
    df_train["P_3"],
    df_train["T_inj"]
)
y_train = df_train["m_dot_i"]  # Target variable


x_test = (
    df_test["rho_inj"],
    df_test["F"],
    df_test["P_1"],
    df_test["P_2"],
    df_test["P_3"],
    df_test["T_inj"]
)
y_test = df_test["m_dot_i"]

y_arr  = np.asarray(y_train, dtype=float)
yscale = np.max(np.abs(y_arr))

# === Curve fitting: try both 'trf' (bounded) and 'lm', keep the one with the lowest training error ===
p0    = [np.mean(y_arr), 1e-3, 1.0, 1.0,  1.0, 1.0]
lower = [-10*yscale, -10*yscale, -2, 1e-3, 1e-3, -20]
upper = [ 10*yscale,  10*yscale,  10,   20,  20,  50]

initial_guess = [0.1, 0.1, 0.1, 1, 1, 1]

fit_options = {
    'trf': dict(p0=p0, bounds=(lower, upper), method='trf', max_nfev=50000),
    'lm':  dict(p0=initial_guess, method='lm', maxfev=1000000),
}

fit_results = {}
for name, opts in fit_options.items():
    try:
        p_fit, cov_fit = curve_fit(fun_I1, x_train, y_arr, **opts)
        sse_fit = np.sum((y_arr - fun_I1(x_train, *p_fit)) ** 2)
        if np.isfinite(sse_fit):
            fit_results[name] = (sse_fit, p_fit, cov_fit)
            print(f"{name}: training SSE = {sse_fit:.6g}, RMSE = {np.sqrt(sse_fit / len(y_arr)):.6g}")
    except Exception as e:
        print(f"{name} failed: {e}")

best_method = min(fit_results, key=lambda k: fit_results[k][0])
_, params, covariance = fit_results[best_method]
print(f"Selected method: {best_method}")
print("Lowest training error: " + best_method.upper() + " (" + ", ".join(f"{k.upper()} SSE = {v[0]:.6g}" for k, v in fit_results.items()) + ")")


# Extract optimized parameters
a0, a1, a2, a3, a4, a5= params
print(f"Optimized Parameters: a0={a0}, a1={a1}, a2={a2},  a3={a3}, a4={a4}, a5={a5} ")

# Make predictions on training and test data
y_pred_train = fun_I1(x_train, *params)
y_pred_test = fun_I1(x_test, *params)

# Compute SSE (Sum of Squared Errors)
SSE_train = np.sum((y_train - y_pred_train) ** 2)
SSE_test = np.sum((y_test - y_pred_test) ** 2)

# Compute R-squared
SS_total_train = np.sum((y_train - np.mean(y_train)) ** 2)
SS_total_test = np.sum((y_test - np.mean(y_test)) ** 2)

R2_train = 1 - (SSE_train / SS_total_train)
R2_test = 1 - (SSE_test / SS_total_test)

rmse_i = root_mean_squared_error(y_test, y_pred_test)
print("RMSE:", rmse_i)

mae_i = mean_absolute_error(y_test, y_pred_test)
print("MAE", mae_i)


# Compute MAPE
mape_train_i = mean_absolute_percentage_error(y_train, y_pred_train) * 100
mape_test_i = mean_absolute_percentage_error(y_test, y_pred_test) * 100


print(f"MAPE (Train): {mape_train_i:.2f}%, MAPE (Test): {mape_test_i:.2f}%")

# Parity plot for training and test data
rel_error = 100 * (np.asarray(y_pred_test) - np.asarray(y_test)) / np.asarray(y_test)
color_limit = 10
band = 0.10

all_values = np.concatenate([y_train, y_pred_train, y_test, y_pred_test])
plot_limit_min = all_values.min() - 0.001
plot_limit_max = all_values.max() + 0.001

x = np.linspace(plot_limit_min, plot_limit_max, 100)
y = x
y_plus_10 = y * 1.1
y_minus_10 = y * 0.9

plt.figure(figsize=(6, 4))
plt.scatter(y_train, y_pred_train, facecolors='none', edgecolors='black',
            marker='o', s=70, linewidths=1.2, zorder=2)

sc = plt.scatter(y_test, y_pred_test, c=rel_error, cmap='coolwarm',
                 vmin=-color_limit, vmax=color_limit, edgecolors='black',
                 marker='o', s=70, linewidths=1, zorder=3)

plt.plot(x, y, color='r', alpha=0.6)
plt.plot(x, y_plus_10, linestyle='--', color='b', alpha=0.6)
plt.plot(x, y_minus_10, linestyle='--', color='b', alpha=0.6)
plt.fill_between(x, y, y_plus_10, color='gray', alpha=0.2)
plt.fill_between(x, y, y_minus_10, color='gray', alpha=0.2)

plt.xlim(plot_limit_min, plot_limit_max)
plt.ylim(plot_limit_min, plot_limit_max)

plt.minorticks_on()
plt.tick_params(direction='in', which='minor', bottom=True, top=True, left=True, right=True, length=3)
plt.tick_params(direction='in', which='major', bottom=True, top=True, left=True, right=True, length=7, labelsize=12)
plt.grid(True, which='major', linestyle='-', linewidth=0.5, color='gray', alpha=0.5)

plt.xlabel("Measured Injection Mass Flow Rate [kg/min]", fontsize=13)
plt.ylabel("Predicted Injection Mass Flow Rate [kg/min]", fontsize=13)

cbar = plt.colorbar(sc, fraction=0.05, pad=0.03)
cbar.set_label("Relative error [%]", fontsize=12)
cbar.ax.tick_params(labelsize=10)

legend_elements = [
    Line2D([0], [0], marker='o', color='black', linestyle='', label='Training data', markerfacecolor='none', markersize=9),
    Line2D([0], [0], linestyle='--', color='b', label='± 10% Error'),
    Line2D([0], [0], linestyle='', label='MAPE = {:.2f} %'.format(mape_test_i))
]
plt.legend(handles=legend_elements, loc='lower right', prop={'size': 9}, handlelength=1.5)

plt.tight_layout()
plt.savefig('Injection.png', dpi=600)
plt.show()
