"Suction Mass Flow Rate Model"

# === 1. Define your injection mass flow rate model ===
def suc_mass_flow(x, b0, b1, b2, b3, b4, b5):
    rho_suc, F, P_1, P_2, P_3, rho_inj   = x
    KB = rho_suc * F * (b0 + b1 * (P_3/P_1) + b2*P_1) + b3*F*rho_inj*(P_2/P_1) -b4*(P_3-P_1)**b5
    return KB

# === 3. Extract input and output variables ===
