mape_train_m = mean_absolute_percentage_error(y_train, y_pred_train) * 100
mape_test_m = mean_absolute_percentage_error(y_test, y_pred_test) * 100
mae = mean_absolute_error(y_test, y_pred_test) * 100
print(f"Optimized Parameters: b0={params[0]:.10f}, b1={params[1]:.10f}, b2={params[2]:.10f}, b3={params[0]:.10f}, b4={params[1]:.10f}, b5={params[2]:.10f}")
print(f"MAPE (Train): {mape_train_m:.2f}%, MAPE (Test): {mape_test_m:.2f}%")

# === 7. Parity Plot ===
rel_error = 100 * (np.asarray(y_pred_test) - np.asarray(y_test)) / np.asarray(y_test)
color_limit = 10
