def Power(x, c0, c1, c2, c3, c4, c5):
    rho_suc, F, P_1, P_2, P_3, rho_inj = x  # Ensure correct input unpacking
    KB2 = c0+ F*rho_suc*(c1*(P_3/P_1)**c2)+c3*F*rho_inj*(P_3/P_2)**c4+c5*(P_3/P_3[3])
    return  KB2


